non_increasing_k = []

for k in range(1, k_max + 1):
    x_k = lcm_list([k, k+1, k+2])
    x_k_plus_1 = lcm_list([k+1, k+2, k+3])

    if x_k_plus_1 <= x_k:
        non_increasing_k.append(k)

print(f"Found {len(non_increasing_k)} values of k <= {k_max} where x_{k+1} <= x_k.")
print("First 20 values of k found:")
print(non_increasing_k[:20])

import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def calculate_x_k(k, n):
