import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

n = 5
# We need x_k up to k=11 to check the 10 steps k=1 to k=10.
K_max = 11
x_values = {}

for k in range(1, K_max + 1):
    sequence = list(range(k, k + n))
    x_k = list_lcm(sequence)
    x_values[k] = x_k
    print(f"x_{k} = lcm({k}, ..., {k+n-1}) = {x_k}")

# Check the sequence for weakly increasing property (x_{k+1} > x_k)
print("\n--- Checking for non-increasing steps ---")
non_increasing_steps = []
for k in range(1, K_max):
    x_k = x_values[k]
    x_k_plus_1 = x_values[k+1]
    if x_k_plus_1 <= x_k:
        non_increasing_steps.append((k, x_k, x_k_plus_1))
        print(f"Non-increasing step found at k={k}: x_{k+1} = {x_k_plus_1} <= x_{k} = {x_k}")

if not non_increasing_steps:
    print("No non-increasing steps found in the initial segment.")
else:
    print(f"Found {len(non_increasing_steps)} non-increasing steps.")

import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

N = 6
K_max = 10
x_values = {}

for k in range(1, K_max + 1):
    sequence = list(range(k, k + N))
    x_k = list_lcm(sequence)
    x_values[k] = x_k

print("k | x_k")
print("-" * 10)
for k in range(1, K_max + 1):
    print(f"{k:2} | {x_values[k]}")

# Check the initial trend for weak increase: x_{k+1} > x_k for k=1 to 9
is_weakly_increasing_initial = True
print("\n--- Trend Check ---")
for k in range(1, K_max):
    if x_values[k+1] <= x_values[k]:
        is_weakly_increasing_initial = False
        print(f"x_{k+1} <= x_k detected: {x_values[k+1]} <= {x_values[k]} at k={k}")
        break
else:
    print("The sequence appears strictly increasing for k=1 to 9.")
